// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address caller, uint256 deposit) public {
        deposit = bound(deposit, 1, 1 ether);
        vm.deal(address(this), deposit);
        (bool sent, ) = address(c).call{value: deposit}("");
        require(sent);

        vm.deal(caller, 1 wei);
        vm.prank(caller);
        bool ok;
        try c.withdrawAll(payable(caller)) {
            ok = true;
        } catch {
            ok = false;
        }

        if (caller == address(this)) {
            assertTrue(address(c).balance <= deposit);
        } else {
            assertTrue(address(c).balance == deposit);
        }
    }
}
